const $=s=>document.querySelector(s),el=(tag,text,parent)=>{const n=document.createElement(tag);n.textContent=text;parent.append(n);return n;};
let lang=initialLanguage(),track=tracks[0],lesson=track.lessons[0],done=new Set(),answers={},warning=false,playing=false,cycle=0,a=20,b=4,kind='',selectedPart='',machine=null,renderer=null,scene=null,camera=null,controls=null,cut=true,apart=false,visible=true,last=0,raf=0;
const params=new URLSearchParams(location.search);track=tracks.find(t=>t.id===params.get('track'))||track;lesson=track.lessons.find(l=>l.id===params.get('lesson'))||track.lessons[0];
try{const data=JSON.parse(localStorage.getItem('mecanica.academy.progress.v1')||'[]');if(Array.isArray(data))done=new Set(data.filter(id=>tracks.some(t=>t.lessons.some(l=>l.id===id))));}catch{warning=true;}
const tr=x=>x[lang],word=k=>ui[lang][k],fmt=(n,d=2)=>new Intl.NumberFormat(lang==='es'?'es-CO':'en-US',{maximumFractionDigits:d}).format(n);
function persist(){try{localStorage.setItem('mecanica.academy.progress.v1',JSON.stringify([...done]));}catch{warning=true;}$('#warning').textContent=warning?word('storage'):'';}
function url(){const p=new URL(location.href);p.searchParams.set('lang',lang);p.searchParams.set('track',track.id);p.searchParams.set('lesson',lesson.id);history.replaceState(null,'',p);}
function progress(){$('#progress').textContent=done.size+' / 20 '+word('progress');$('#progressBar').value=done.size;}
function resetParameters(){cycle=0;playing=false;const mode=lesson.lab||track.lab;if(mode==='dc'){a=12;b=1000;}else if(mode==='opamp'){a=2;b=5;}else if(['sine','rectifier','threephase'].includes(mode)){a=10;b=50;}else{a=track.id==='pneumatics'?4:20;b=4;}}
function makeRange(key,min,max,step,value,change){const label=el('label',word(key)+' · '+fmt(value),$('#parameters'));const input=el('input','',label);input.type='range';input.min=min;input.max=max;input.step=step;input.value=value;input.dataset.parameter=key;input.oninput=()=>{change(+input.value);label.firstChild.textContent=word(key)+' · '+fmt(+input.value);draw();};}
function renderParameters(){const root=$('#parameters');root.replaceChildren();const mode=lesson.lab||track.lab;if(mode==='hydraulic'){makeRange('force',5,100,5,a,v=>a=v);makeRange('ratio',1,6,.5,b,v=>b=v);}else if(mode==='pneumatic')makeRange('pressure',1,8,.5,a,v=>a=v);else if(mode==='dc'){makeRange('voltage',0,24,.5,a,v=>a=v);makeRange('resistance',100,3000,100,b,v=>b=v);}else if(['sine','rectifier','threephase','opamp'].includes(mode)){makeRange('amplitude',.5,10,.5,a,v=>a=v);makeRange(mode==='opamp'?'gain':'frequency',mode==='opamp'?1:10,mode==='opamp'?10:100,mode==='opamp'?.5:10,b,v=>b=v);}}
function setLesson(t,l){track=t;lesson=l;resetParameters();render();$('#lessonTitle').scrollIntoView({block:'start'});}
function render(){document.documentElement.lang=lang;document.title=tr(track.name)+' · Workshop Academy';$('#language').value=lang;for(const [id,key]of Object.entries({home:'home',languageLabel:'language',title:'title',intro:'intro',ready:'ready',routeLabel:'route',objectiveLabel:'objective',explanationLabel:'explanation',exampleLabel:'example',practiceLabel:'practice',mistakeLabel:'mistake',checkLabel:'check',labLabel:'lab',cut:'cut',explode:'explode',reset:'reset',cycleLabel:'cycle',caption:'caption',limitsLabel:'limits',readoutLabel:'readout',previous:'previous',next:'next',saved:'saved',legacy:'legacy',sourcesLabel:'sources'}))$('#'+id).textContent=word(key);
 $('#tracks').setAttribute('aria-label',word('route'));$('#lessons').setAttribute('aria-label',tr(track.name));$('#tracks').replaceChildren();for(const t of tracks){const button=el('button',tr(t.name),$('#tracks'));button.setAttribute('aria-pressed',String(t===track));el('small',t.lessons.filter(l=>done.has(l.id)).length+' / '+t.lessons.length,button);button.dataset.track=t.id;button.onclick=()=>setLesson(t,t.lessons[0]);}
 $('#trackIntro').textContent=tr(track.intro);$('#connectedCase').textContent=lang==='es'?'Caso guiado en 3D →':'Guided 3D case →';$('#connectedCase').href='workshop.html?case='+track.id+'&lang='+lang;$('#lessons').replaceChildren();for(const l of track.lessons){const button=el('button',(done.has(l.id)?'✓ ':'')+tr(l.title),$('#lessons'));button.dataset.lesson=l.id;button.setAttribute('aria-current',l===lesson?'step':'false');button.setAttribute('aria-pressed',String(l===lesson));button.onclick=()=>setLesson(track,l);}
 $('#lessonCount').textContent=word('route')+' '+(tracks.indexOf(track)+1)+' / 4 · '+(track.lessons.indexOf(lesson)+1)+' / 5';for(const [id,field]of Object.entries({lessonTitle:'title',goal:'goal',body:'body',example:'example',practice:'practice',mistake:'mistake',question:'question'}))$('#'+id).textContent=tr(lesson[field]);$('#formula').textContent=lesson.formula;
 $('#answers').replaceChildren();lesson.answers.forEach((answer,i)=>{const btn=el('button',tr(answer),$('#answers'));btn.dataset.answer=i;btn.setAttribute('aria-pressed',String(answers[lesson.id]===i));btn.onclick=()=>{answers[lesson.id]=i;if(i===lesson.correct){done.add(lesson.id);persist();}render();};});const chosen=answers[lesson.id];$('#feedback').textContent=chosen===undefined?'':word(chosen===lesson.correct?'correct':'incorrect')+' '+tr(depth[lesson.id].why[chosen]);$('#next').disabled=!done.has(lesson.id);$('#previous').disabled=tracks.indexOf(track)===0&&track.lessons.indexOf(lesson)===0;
 $('#sources').replaceChildren();for(const source of sources){const link=el('a',source.name,$('#sources'));link.href=source.url;link.target='_blank';link.rel='noopener';}$('#warning').textContent=warning?word('storage'):'';renderDepth(lesson,track,lang);renderParameters();progress();url();prepareLab();renderParts();draw();}
function renderParts(){const list=parts[track.lab]||[];if(!list.some(p=>p.id===selectedPart))selectedPart=list[0]?.id||'';$('#parts').replaceChildren();for(const part of list){const btn=el('button',part[lang].split(' — ')[0],$('#parts'));btn.dataset.part=part.id;btn.setAttribute('aria-pressed',String(part.id===selectedPart));btn.onclick=()=>{selectedPart=part.id;renderParts();draw();};}$('#partCopy').textContent=list.find(p=>p.id===selectedPart)?.[lang]||'';machine?.select(selectedPart);}
function dispose(){if(!scene)return;controls?.dispose();scene.traverse(o=>{o.geometry?.dispose();const mats=Array.isArray(o.material)?o.material:o.material?[o.material]:[];for(const m of mats){m.map?.dispose();m.dispose();}});renderer?.dispose();$('#viewport').replaceChildren();renderer=null;scene=null;machine=null;}
function prepareLab(){const next=track.lab;$('#viewport').hidden=next==='signal';$('#signalPlot').toggleAttribute('hidden',next!=='signal');$('#plotScroll').hidden=next!=='signal';$('#plotScroll').setAttribute('aria-label',word('graphCaption')); $('#cut').hidden=$('#explode').hidden=next==='signal';$('#caption').textContent=word(next==='signal'?'graphCaption':'caption');$('#cycle').hidden=$('#cycleLabel').hidden=(lesson.lab==='dc');$('#play').hidden=lesson.lab==='dc';$('#limits').textContent=word(next==='signal'?'signalLimit':next==='engine'?'engineLimit':next==='hydraulic'?'hydraulicLimit':'pneumaticLimit');if(kind===next){if(kind!=='signal'&&!renderer)$('#viewport').textContent=word('no3d');return;}dispose();kind=next;if(kind==='signal')return;
 try{renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));$('#viewport').append(renderer.domElement);scene=new T.Scene();scene.background=new T.Color(0xe8ecdf);scene.add(new T.HemisphereLight(0xffffff,0x73816c,3));const sun=new T.DirectionalLight(0xffefd3,3);sun.position.set(4,8,6);scene.add(sun);camera=new T.PerspectiveCamera(38,1,.1,100);controls=new OrbitControls(camera,renderer.domElement);controls.minDistance=4;controls.maxDistance=40;machine=buildMachine(kind,scene);machine.setCut(cut);controls.addEventListener('change',()=>renderer?.render(scene,camera));resize();}catch{dispose();$('#viewport').textContent=word('no3d');}}
function resize(){if(!renderer)return;const host=$('#viewport'),w=host.clientWidth,h=host.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();const scale=Math.max(1,1.1/camera.aspect),wide=kind==='pneumatic'?1.35:1;camera.position.set(7*scale*wide,6*scale,10*scale*wide);controls.target.set(0,kind==='engine'?2.4:1.5,0);controls.update();draw();}
new ResizeObserver(resize).observe($('#viewport'));
const svgNS='http://www.w3.org/2000/svg';function svg(tag,attrs,text){const n=document.createElementNS(svgNS,tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,String(v));if(text)n.textContent=text;$('#signalPlot').append(n);return n;}
function drawGraph(mode){const root=$('#signalPlot');root.replaceChildren();root.setAttribute('aria-label',tr(lesson.title)+' · '+word('readout'));svg('title',{},tr(lesson.title));for(let i=0;i<=4;i++){const x=60+i*170;svg('line',{x1:x,y1:30,x2:x,y2:270,stroke:'#c0cab3'});svg('text',{x,y:295,'font-size':14,fill:'#21392f'},String(i*10)+' ms');}svg('line',{x1:60,y1:150,x2:740,y2:150,stroke:'#7e8f7c'});const max=mode==='opamp'?Math.max(12,a):Math.max(1,a);for(const y of [-1,0,1])svg('text',{x:4,y:155-y*110,'font-size':14,fill:'#21392f'},fmt(y*max)+' V');
 const wave=(fn,color)=>{let d='';for(let i=0;i<=240;i++){const t=i/240*.04;d+=(i?'L':'M')+(60+i/240*680).toFixed(2)+','+(150-fn(t)*110/max).toFixed(2);}svg('path',{d,fill:'none',stroke:color,'stroke-width':2.5});};
 if(mode==='dc'){wave(()=>a,'#376e69');return;}const shift=cycle*(mode==='opamp'?1/50:1/b);wave(t=>a*Math.sin(2*Math.PI*(mode==='opamp'?50:b)*(t+shift)),'#376e69');if(mode==='threephase'){for(const [phase,color]of [[-2*Math.PI/3,'#a56331'],[-4*Math.PI/3,'#765889']])wave(t=>waveValue(mode,a,b,t+shift,phase),color);}if(mode==='opamp'||mode==='rectifier')wave(t=>waveValue(mode,a,b,t+shift),'#a56331');svg('text',{x:60,y:20,'font-size':14,fill:'#376e69'},word('input')+' / A');if(mode==='rectifier'||mode==='opamp')svg('text',{x:360,y:20,'font-size':14,fill:'#a56331'},word('output'));if(mode==='threephase'){svg('text',{x:300,y:20,'font-size':14,fill:'#a56331'},'B −120°');svg('text',{x:520,y:20,'font-size':14,fill:'#765889'},'C −240°');}}
function draw(){let model,text='';const mode=lesson.lab||track.lab;if(kind==='engine'){model=engineState(cycle);text=word(['intake','compression','power','exhaust'][model.phase])+' · '+fmt(cycle*720,0)+'° / 720°';}else if(kind==='hydraulic'){model=pressState(cycle,a,b);text='p = '+fmt(model.pressure/1e5)+' bar\n'+word('input')+': '+fmt(a)+' N · '+fmt(model.inputMM)+' mm\n'+word('output')+': '+fmt(model.outputForce)+' N · '+fmt(model.outputMM)+' mm';}else if(kind==='pneumatic'){model=pneumaticState(cycle,a,40);text=word(model.advance?'extend':'retract')+' · '+model.paths.join(' / ')+'\n'+fmt(model.positionMM)+' mm · F = '+fmt(Math.abs(model.force),0)+' N\npA = '+fmt(model.pA)+' bar · pB = '+fmt(model.pB)+' bar';}else{const m=signalModel(mode,a,b,cycle/50);drawGraph(mode);text=mode==='dc'?'I = '+fmt(m.current*1000)+' mA · P = '+fmt(m.power)+' W':mode==='opamp'?'Av = '+fmt(b)+' · '+word(m.clipped?'clipping':'linear')+'\nVin = '+fmt(m.input)+' V · Vout = '+fmt(m.output)+' V':mode==='threephase'?'V RMS ('+word('phase')+') = '+fmt(m.rms)+' V · V RMS ('+word('line')+', Y) = '+fmt(m.lineRms)+' V':'Vin RMS = '+fmt(m.rms)+' V · T = '+fmt(m.period)+' ms'+(mode==='rectifier'?' · '+word('ripple')+' = '+fmt(m.rippleFrequency)+' Hz':'');}
 if(model&&machine){machine.update(model,apart?1:0,cycle);renderer.render(scene,camera);}$('#readout').textContent=text;$('#cycle').value=Math.round(cycle*999);$('#play').textContent=word(playing?'pause':'play');$('#cut').setAttribute('aria-pressed',String(cut));$('#explode').setAttribute('aria-pressed',String(apart));}
function animate(t){raf=0;if(!playing||!visible||document.hidden)return;const dt=last?Math.min(.05,(t-last)/1000):0;last=t;cycle=(cycle+dt*.12)%1;draw();raf=requestAnimationFrame(animate);}
function schedule(){if(playing&&visible&&!document.hidden&&!raf){last=0;raf=requestAnimationFrame(animate);}}
new IntersectionObserver(([e])=>{visible=e.isIntersecting;schedule();}).observe($('.lab'));document.addEventListener('visibilitychange',schedule);matchMedia('(prefers-reduced-motion:reduce)').addEventListener('change',()=>{playing=false;draw();});
$('#play').onclick=()=>{playing=!playing;draw();schedule();};$('#cycle').oninput=e=>{playing=false;cycle=+e.target.value/1000;draw();};$('#cut').onclick=()=>{cut=!cut;machine?.setCut(cut);draw();};$('#explode').onclick=()=>{apart=!apart;playing=false;draw();};$('#reset').onclick=()=>{resetParameters();apart=false;cut=true;machine?.setCut(true);renderParameters();resize();draw();};$('#language').onchange=e=>{lang=e.target.value;try{localStorage.setItem('mecanica.locale.v1',lang);}catch{warning=true;}render();};
$('#previous').onclick=()=>{const i=track.lessons.indexOf(lesson),j=tracks.indexOf(track);if(i>0)setLesson(track,track.lessons[i-1]);else if(j>0)setLesson(tracks[j-1],tracks[j-1].lessons.at(-1));};$('#next').onclick=()=>{if(!done.has(lesson.id))return;const i=track.lessons.indexOf(lesson),j=tracks.indexOf(track);if(i<4)setLesson(track,track.lessons[i+1]);else if(j<3)setLesson(tracks[j+1],tracks[j+1].lessons[0]);else $('#feedback').textContent=word('finish');};
resetParameters();render();window.academyDebug=()=>({lang,track:track.id,lesson:lesson.id,done:[...done],kind,cycle,a,b,playing,parts:machine?.partCount});
